files.content:
:root {
  --bg: #1a1c2c;
  --card: #29366f;
  --panel: #3b5dc9;
  --accent: #ffcd75;
  --accent-dark: #e6a93b;
  --text: #f4f4f4;
  --muted: #b8c2e0;
  --success: #a7f070;
  --shadow: #0d0f1a;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background-color: var(--bg);
  background-image:
    linear-gradient(rgba(255, 205, 117, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 205, 117, 0.06) 1px, transparent 1px);
  background-size: 24px 24px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--text);
  border-radius: 0;
  box-shadow: 8px 8px 0 var(--shadow), 0 0 0 4px var(--card), 0 0 0 8px var(--shadow);
  padding: 28px 24px 24px;
}

.title {
  margin: 0 0 24px;
  font-size: 1.75rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-align: center;
  color: var(--accent);
  text-shadow: 3px 3px 0 var(--shadow);
}

.field {
  margin: 0 0 20px;
  padding: 0;
  border: 0;
}

.field > label,
.field > legend {
  display: block;
  margin-bottom: 8px;
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--muted);
  text-transform: uppercase;
}

.input-wrap {
  display: flex;
  align-items: stretch;
  background: var(--bg);
  border: 3px solid var(--text);
  box-shadow: 4px 4px 0 var(--shadow);
}

.prefix {
  display: flex;
  align-items: center;
  padding: 0 12px;
  font-weight: 700;
  color: var(--accent);
  background: var(--bg);
  border-right: 3px solid var(--text);
}

input[type="number"] {
  width: 100%;
  min-width: 0;
  padding: 12px;
  font: inherit;
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--text);
  border-radius: 0;
  box-shadow: 4px 4px 0 var(--shadow);
  outline: none;
}

.input-wrap input[type="number"] {
  border: 0;
  box-shadow: none;
}

input[type="number"]:focus-visible,
.input-wrap:focus-within {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.tip-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.tip-btn {
  padding: 14px 8px;
  font: inherit;
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--bg);
  background: var(--accent);
  border: 3px solid var(--text);
  border-radius: 0;
  box-shadow: 4px 4px 0 var(--shadow);
  cursor: pointer;
  transition: transform 0.05s ease, box-shadow 0.05s ease, background 0.15s ease;
}

.tip-btn:hover {
  background: var(--accent-dark);
}

.tip-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.tip-btn:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 var(--shadow);
}

.tip-btn[aria-pressed="true"] {
  background: var(--success);
  color: var(--bg);
  box-shadow: inset 4px 4px 0 rgba(0, 0, 0, 0.25);
}

.tip-btn[aria-pressed="true"]:hover {
  background: #8fd85a;
}

.results {
  margin-top: 8px;
  padding: 16px;
  background: var(--bg);
  border: 3px solid var(--text);
  box-shadow: 4px 4px 0 var(--shadow);
}

.result-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
}

.result-row + .result-row {
  border-top: 2px dashed var(--panel);
}

.result-label {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--muted);
}

.result-value {
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.result-row.total .result-value {
  color: var(--success);
}

@media (max-width: 400px) {
  .card {
    padding: 22px 16px 18px;
    box-shadow: 6px 6px 0 var(--shadow), 0 0 0 3px var(--card), 0 0 0 6px var(--shadow);
  }

  .title {
    font-size: 1.5rem;
  }

  .tip-btn {
    padding: 12px 4px;
    font-size: 1rem;
  }

  .result-value {
    font-size: 1.25rem;
  }
}

(function () {
  'use strict';

  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var tipButtons = Array.prototype.slice.call(document.querySelectorAll('.tip-btn'));
  var tipPerPersonEl = document.getElementById('tip-per-person');
  var totalPerPersonEl = document.getElementById('total-per-person');

  var selectedTip = 15;

  function formatMoney(value) {
    if (!isFinite(value) || value < 0) value = 0;
    return '$' + value.toFixed(2);
  }

  function parseNumber(input) {
    var raw = input.value.trim();
    if (raw === '') return NaN;
    var n = Number(raw);
    return isFinite(n) ? n : NaN;
  }

  function calculate() {
    var bill = parseNumber(billInput);
    var people = parseNumber(peopleInput);

    if (!isFinite(bill) || bill < 0) bill = 0;
    if (!isFinite(people) || people < 1) people = 1;

    var tipTotal = bill * (selectedTip / 100);
    var grandTotal = bill + tipTotal;
    var tipPerPerson = tipTotal / people;
    var totalPerPerson = grandTotal / people;

    tipPerPersonEl.textContent = formatMoney(tipPerPerson);
    totalPerPersonEl.textContent = formatMoney(totalPerPerson);
  }

  function selectTip(button) {
    selectedTip = Number(button.getAttribute('data-tip'));
    tipButtons.forEach(function (btn) {
      var isSelected = btn === button;
      btn.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
    });
    calculate();
  }

  tipButtons.forEach(function (button) {
    button.addEventListener('click', function () {
      selectTip(button);
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  // Initialize default selection (15%) and results.
  var defaultButton = tipButtons.find(function (btn) {
    return Number(btn.getAttribute('data-tip')) === selectedTip;
  });
  if (defaultButton) {
    defaultButton.setAttribute('aria-pressed', 'true');
  }
  calculate();
})();
